using Microsoft.AspNetCore.Mvc;
using RaceDay.Web.Models;
using RaceDay.Web.Services;
using System.Text.Json;
namespace RaceDay.Web.Controllers;
public class OrganizerController(RaceDayApiClient api) : Controller
{
    private bool Allowed()=>HttpContext.Session.GetString("Role")=="Organizer";
    public async Task<IActionResult> Index(){if(!Allowed())return RedirectToAction("Login","Account"); var all=await api.GetAsync<List<JsonElement>>(HttpContext,"api/events")??new(); var me=HttpContext.Session.GetInt32("UserId"); var mine=all.Where(e=>e.TryGetProperty("organizerID",out var owner)&&owner.GetInt32()==me).ToList(); var counts=new Dictionary<int,int>(); foreach(var ev in mine){var eventId=ev.TryGetProperty("eventID",out var eid)?eid.GetInt32():0; var enrollments=await api.GetAsync<List<JsonElement>>(HttpContext,$"api/enrollments/event/{eventId}")??new(); counts[eventId]=enrollments.Count;} ViewBag.Events=mine; ViewBag.EnrollmentCounts=counts; return View();}
    [HttpGet] public IActionResult CreateEvent(){if(!Allowed())return RedirectToAction("Login","Account");return View(new EventViewModel());}
    [HttpPost][ValidateAntiForgeryToken] public async Task<IActionResult> CreateEvent(EventViewModel m,IFormFile? banner){if(!Allowed())return Forbid(); if(!ModelState.IsValid)return View(m); using var r=await api.JsonAsync(HttpContext,HttpMethod.Post,"api/events",m); if(!r.IsSuccessStatusCode){ModelState.AddModelError("","API rejected the event. Check required fields and event status.");return View(m);} var created=await r.Content.ReadFromJsonAsync<JsonElement>(); int id=created.TryGetProperty("eventID",out var v)?v.GetInt32():created.GetProperty("EventID").GetInt32(); if(banner!=null&&banner.Length>0){using var form=new MultipartFormDataContent(); await using var s=banner.OpenReadStream();var part=new StreamContent(s);part.Headers.ContentType=new System.Net.Http.Headers.MediaTypeHeaderValue(banner.ContentType);form.Add(part,"file",banner.FileName);using var upload=await api.SendAsync(HttpContext,HttpMethod.Post,$"api/events/{id}/banner",form);if(!upload.IsSuccessStatusCode)TempData["Error"]="Event created, but banner upload failed.";} TempData["Success"]="Event created.";return RedirectToAction(nameof(Index));}
    [HttpGet] public async Task<IActionResult> EditEvent(int id){if(!Allowed())return Forbid();var e=await api.GetAsync<EventViewModel>(HttpContext,$"api/events/{id}");return e==null?NotFound():View(e);}
    [HttpPost][ValidateAntiForgeryToken] public async Task<IActionResult> EditEvent(int id,EventViewModel m,IFormFile? banner){if(!Allowed())return Forbid();if(!ModelState.IsValid)return View(m);using var r=await api.JsonAsync(HttpContext,HttpMethod.Put,$"api/events/{id}",m);if(!r.IsSuccessStatusCode){ModelState.AddModelError("","Could not update event.");return View(m);}if(banner!=null&&banner.Length>0){using var form=new MultipartFormDataContent();await using var s=banner.OpenReadStream();var part=new StreamContent(s);part.Headers.ContentType=new System.Net.Http.Headers.MediaTypeHeaderValue(banner.ContentType);form.Add(part,"file",banner.FileName);using var up=await api.SendAsync(HttpContext,HttpMethod.Post,$"api/events/{id}/banner",form);}return RedirectToAction(nameof(Index));}
    [HttpPost][ValidateAntiForgeryToken] public async Task<IActionResult> DeleteEvent(int id){if(!Allowed())return Forbid();using var r=await api.SendAsync(HttpContext,HttpMethod.Delete,$"api/events/{id}");TempData[r.IsSuccessStatusCode?"Success":"Error"]=r.IsSuccessStatusCode?"Event deleted.":"Could not delete event.";return RedirectToAction(nameof(Index));}
    public async Task<IActionResult> Categories(int id){if(!Allowed())return Forbid();ViewBag.EventId=id;ViewBag.Categories=await api.GetAsync<List<JsonElement>>(HttpContext,$"api/events/{id}/categories")??new();return View();}
    [HttpPost][ValidateAntiForgeryToken] public async Task<IActionResult> AddCategory(int id,CategoryViewModel m){if(!Allowed())return Forbid();if(!ModelState.IsValid)return RedirectToAction(nameof(Categories),new{id});using var r=await api.JsonAsync(HttpContext,HttpMethod.Post,$"api/events/{id}/categories",m);TempData[r.IsSuccessStatusCode?"Success":"Error"]=r.IsSuccessStatusCode?"Category added.":"Category could not be added.";return RedirectToAction(nameof(Categories),new{id});}
    public async Task<IActionResult> Enrollments(int id){if(!Allowed())return Forbid();ViewBag.EventId=id;ViewBag.Rows=await api.GetAsync<List<JsonElement>>(HttpContext,$"api/enrollments/event/{id}")??new();return View();}
    [HttpGet] public async Task<IActionResult> RecordResult(int enrollmentId){if(!Allowed())return Forbid();ViewBag.EnrollmentId=enrollmentId;return View();}
    [HttpPost][ValidateAntiForgeryToken] public async Task<IActionResult> RecordResult(int enrollmentId,int? finishTimeSeconds,int? position,string resultStatus="Finished"){if(!Allowed())return Forbid();using var r=await api.JsonAsync(HttpContext,HttpMethod.Post,$"api/enrollments/{enrollmentId}/result",new{finishTimeSeconds,position,resultStatus});TempData[r.IsSuccessStatusCode?"Success":"Error"]=r.IsSuccessStatusCode?"Result saved.":"Result could not be saved.";return RedirectToAction(nameof(Index));}
}
